def split_csv_line(line: str) -> list[str]:
    fields = []
    i = 0
    n = len(line)
    while True:
        if i < n and line[i] == '"':
            i += 1
            buf = []
            while i < n:
                c = line[i]
                if c == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        buf.append('"')
                        i += 2
                        continue
                    i += 1
                    break
                buf.append(c)
                i += 1
            while i < n and line[i] != ',':
                buf.append(line[i])
                i += 1
            fields.append(''.join(buf))
        else:
            j = line.find(',', i)
            if j == -1:
                j = n
            fields.append(line[i:j])
            i = j
        if i >= n:
            break
        i += 1
        if i >= n:
            fields.append('')
            break
    return fields
